{"content":"<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Message Board</title>
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
      background-color: #f5f5f5;
      color: #333;
      min-height: 100vh;
    }

    .container {
      max-width: 640px;
      margin: 0 auto;
      padding: 24px 16px;
    }

    header {
      text-align: center;
      margin-bottom: 24px;
    }

    header h1 {
      font-size: 1.75rem;
      color: #1a1a1a;
    }

    header p {
      color: #666;
      font-size: 0.875rem;
      margin-top: 4px;
    }

    .status-bar {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 8px;
      margin-bottom: 16px;
      border-radius: 8px;
      font-size: 0.8rem;
      font-weight: 500;
    }

    .status-bar.connected {
      background-color: #d4edda;
      color: #155724;
    }

    .status-bar.disconnected {
      background-color: #f8d7da;
      color: #721c24;
    }

    .status-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
    }

    .connected .status-dot {
      background-color: #28a745;
    }

    .disconnected .status-dot {
      background-color: #dc3545;
    }

    .message-form {
      display: flex;
      gap: 8px;
      margin-bottom: 24px;
    }

    .message-form input {
      flex: 1;
      padding: 12px 16px;
      border: 1px solid #ddd;
      border-radius: 8px;
      font-size: 1rem;
      outline: none;
      transition: border-color 0.2s;
    }

    .message-form input:focus {
      border-color: #4a90d9;
      box-shadow: 0 0 0 2px rgba(74, 144, 217, 0.15);
    }

    .message-form button {
      padding: 12px 24px;
      background-color: #4a90d9;
      color: white;
      border: none;
      border-radius: 8px;
      font-size: 1rem;
      font-weight: 500;
      cursor: pointer;
      transition: background-color 0.2s;
    }

    .message-form button:hover {
      background-color: #3a7bc8;
    }

    .message-form button:active {
      background-color: #2e6ab0;
    }

    .message-list {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

