    .message-item .message-text {
      word-break: break-word;
      line-height: 1.5;
    }

    .message-item .message-time {
      font-size: 0.75rem;
      color: #999;
      margin-top: 4px;
    }

    .empty-state {
      text-align: center;
      padding: 48px 16px;
      color: #999;
    }

    .empty-state p {
      font-size: 1rem;
