    }

    .status-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
    }

    .connected .status-dot {
      background-color: #28a745;
    }

    .disconnected .status-dot {
      background-color: #dc3545;
    }

    .message-form {
      display: flex;
      gap: 8px;
      margin-bottom: 24px;
    }

    .message-form input {
