import express from 'express';
import cors from 'cors';
import { createRequire } from 'module';
import { existsSync, mkdirSync } from 'fs';
import { resolve } from 'path';

const require = createRequire(import.meta.url);
const pglite = require('@electric-sql/pglite');
const PGLite = pglite['PGlite'];

const app = express();
const PORT = 3001;

// Middleware
app.use(cors());
app.use(express.json());

// SSE connections tracker
const sseConnections = new Set();

// Broadcast a message to all connected SSE clients
function broadcast(data) {
  const message = `data: ${JSON.stringify(data)}\n\n`;
  for (const res of sseConnections) {
    try {
      res.write(message);
    } catch (err) {
      // Connection may have been closed, remove it
      sseConnections.delete(res);
    }
  }
}

// Initialize PGLite with filesystem persistence
const dbPath = resolve(process.cwd(), 'pglite-data');
if (!existsSync(dbPath)) {
  mkdirSync(dbPath, { recursive: true });
}

let db;

async function initDatabase() {
  db = new PGLite({
    dataDir: dbPath
  });

  await db.waitReady;

  // Create the messages table if it doesn't exist
  await db.query(`
    CREATE TABLE IF NOT EXISTS messages (
      id SERIAL PRIMARY KEY,
      text TEXT NOT NULL,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
    )
  `);

  console.log('Database initialized successfully');
}

// GET /api/messages - Fetch all historical messages
app.get('/api/messages', async (req, res) => {
  try {
    const result = await db.query('SELECT id, text, created_at FROM messages ORDER BY created_at ASC');
    res.json(result.rows);
  } catch (err) {
    console.error('Error fetching messages:', err);
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// POST /api/messages - Insert a new message and broadcast via SSE
app.post('/api/messages', async (req, res) => {
  try {
    const { text } = req.body;

    if (!text || !text.trim()) {
      return res.status(400).json({ error: 'Message text is required' });
    }

    const result = await db.query(
      'INSERT INTO messages (text) VALUES ($1) RETURNING id, text, created_at',
      [text.trim()]
    );

    const newMessage = result.rows[0];

    // Broadcast to all SSE clients
    broadcast(newMessage);

    res.status(201).json(newMessage);
  } catch (err) {
    console.error('Error inserting message:', err);
    res.status(500).json({ error: 'Failed to post message' });
  }
});

// GET /api/stream - SSE endpoint for real-time updates
app.get('/api/stream', (req, res) => {
  // Set SSE headers
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');

  // Send initial comment to keep connection alive
  res.write(': connected\n\n');

  // Add to active connections
  sseConnections.add(res);

  // Handle client disconnect
  req.on('close', () => {
    sseConnections.delete(res);
  });

  req.on('error', () => {
    sseConnections.delete(res);
  });
});

// Start server
async function start() {
  try {
    await initDatabase();
    app.listen(PORT, () => {
      console.log(`Server running on http://localhost:${PORT}`);
    });
  } catch (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
}

start();

// DOM elements
const messageForm = document.getElementById('message-form');
const messageInput = document.getElementById('message-input');
const messageList = document.getElementById('message-list');
const emptyState = document.getElementById('empty-state');
const statusBar = document.getElementById('status-bar');
const statusText = document.getElementById('status-text');

// State
let eventSource = null;

// Format a timestamp into a readable string
function formatTime(timestamp) {
  const date = new Date(timestamp);
  const now = new Date();
  const isToday = date.toDateString() === now.toDateString();

  const timeStr = date.toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit'
  });

  if (isToday) {
    return `Today at ${timeStr}`;
  }

  const yesterday = new Date(now);
  yesterday.setDate(yesterday.getDate() - 1);
  if (date.toDateString() === yesterday.toDateString()) {
    return `Yesterday at ${timeStr}`;
  }

  return date.toLocaleDateString([], {
    month: 'short',
    day: 'numeric',
    year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined
  }) + ` at ${timeStr}`;
}

// Create a message element
function createMessageElement(message) {
  const div = document.createElement('div');
  div.className = 'message-item';
  div.dataset.id = message.id;

  const textDiv = document.createElement('div');
  textDiv.className = 'message-text';
  textDiv.textContent = message.text;

  const timeDiv = document.createElement('div');
  timeDiv.className = 'message-time';
  timeDiv.textContent = formatTime(message.created_at);

  div.appendChild(textDiv);
  div.appendChild(timeDiv);

  return div;
}

// Update empty state visibility
function updateEmptyState() {
  const messages = messageList.querySelectorAll('.message-item');
  if (messages.length === 0) {
    emptyState.style.display = 'block';
  } else {
    emptyState.style.display = 'none';
  }
}

// Set connection status
function setStatus(connected) {
  statusBar.className = `status-bar ${connected ? 'connected' : 'disconnected'}`;
  statusText.textContent = connected ? 'Live' : 'Disconnected';
}

// Fetch initial messages from the API
async function fetchMessages() {
  try {
    const response = await fetch('/api/messages');
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    const messages = await response.json();

    // Clear existing messages (except empty state)
    messageList.querySelectorAll('.message-item').forEach(el => el.remove());

    // Render all messages
    for (const message of messages) {
      messageList.appendChild(createMessageElement(message));
    }

    updateEmptyState();
  } catch (err) {
    console.error('Failed to fetch messages:', err);
    statusText.textContent = 'Error loading messages';
  }
}

// Connect to SSE stream
function connectSSE() {
  // Close existing connection if any
  if (eventSource) {
    eventSource.close();
  }

  eventSource = new EventSource('/api/stream');

  eventSource.onopen = () => {
    setStatus(true);
  };

  eventSource.onmessage = (event) => {
    try {
      const message = JSON.parse(event.data);
      messageList.appendChild(createMessageElement(message));
      updateEmptyState();

      // Scroll to bottom to show new message
      messageList.scrollTop = messageList.scrollHeight;
    } catch (err) {
      console.error('Failed to parse SSE message:', err);
    }
  };

  eventSource.onerror = () => {
    setStatus(false);
    // EventSource will automatically reconnect
  };
}

// Post a new message
async function postMessage(text) {
  try {
    const response = await fetch('/api/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ text })
    });

    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'Failed to post message');
    }

    // Clear the input
    messageInput.value = '';
    messageInput.focus();
  } catch (err) {
    console.error('Failed to post message:', err);
    alert(err.message || 'Failed to post message. Please try again.');
  }
}

// Event listeners
messageForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const text = messageInput.value.trim();
  if (text) {
    postMessage(text);
  }
});

// Initialize
fetchMessages();
connectSSE();

import { defineConfig } from 'vite';

export default defineConfig({
  server: {
    port: 5173,
    proxy: {
      '/api': {
        target: 'http://localhost:3001',
        changeOrigin: true,
        ws: true
      }
    }
  }
});

